-- Baseline schema for rutaseg on PostgreSQL.
-- Generated from the JPA model on 2026-04-30. Once this file ships, schema changes
-- go in new V<n>__<description>.sql files; do not edit this one in place.

create table users (
    id       bigint generated by default as identity primary key,
    nickname varchar(255),
    password varchar(255),
    email    varchar(255),
    admin    boolean not null,
    constraint unique_email unique (email)
);

create table driver_datas (
    id      bigint generated by default as identity primary key,
    name    varchar(255),
    phone   varchar(255),
    chasis  varchar(255),
    semi    varchar(255),
    company varchar(255)
);

create table customs_datas (
    id    bigint generated by default as identity primary key,
    name  varchar(255),
    phone varchar(255)
);

create table consignee_datas (
    id   bigint generated by default as identity primary key,
    name varchar(255),
    cuit bigint
);

create table clients (
    id      bigint generated by default as identity primary key,
    user_id bigint,
    name    varchar(255),
    phone   varchar(255),
    cuit    bigint,
    constraint "uk_clients-user"  unique (user_id),
    constraint "fk_clients-users" foreign key (user_id) references users (id)
);

-- Client.consignees @ElementCollection
create table consignees (
    client_id bigint not null,
    name      varchar(255),
    cuit      bigint  not null,
    constraint "fk_consignees-clients" foreign key (client_id) references clients (id)
);

create table orders (
    id                 bigint generated by default as identity primary key,
    code               varchar(255),
    status             varchar(255),
    client_id          bigint not null,
    pema               boolean not null,
    port               boolean not null,
    transport          boolean not null,
    arrival_date       date,
    arrival_time       time,
    origin             varchar(255),
    target             varchar(255),
    free_load          boolean not null,
    driver_data_id     bigint,
    customs_data_id    bigint,
    consignee_id       bigint,
    container_qty      integer not null,
    free_load_qty      integer not null,
    returned           boolean not null,
    billed             boolean not null,
    created_by_user_id bigint  not null,
    created_at         timestamp(6) with time zone,
    created_at_idx     bigint  not null,
    finished_at        timestamp(6) with time zone,
    constraint "uk_orders-driver_data"     unique (driver_data_id),
    constraint "uk_orders-customs_data"    unique (customs_data_id),
    constraint "uk_orders-consignee"       unique (consignee_id),
    constraint "fk_orders-clients"         foreign key (client_id)       references clients         (id),
    constraint "fk_orders-driver_datas"    foreign key (driver_data_id)  references driver_datas    (id),
    constraint "fk_orders-customs_data"    foreign key (customs_data_id) references customs_datas   (id),
    constraint "fk_orders-consignee_datas" foreign key (consignee_id)    references consignee_datas (id)
);

create index "IDX_ORDERS_CODE"                  on orders (code);
create index "IDX_ORDERS_ARRIVAL_DATE_CLIENT_ID" on orders (arrival_date, client_id);
create index "IDX_ORDERS_CREATED_AT"            on orders (created_at_idx);

create table containers (
    id        bigint generated by default as identity primary key,
    order_id  bigint,
    code      varchar(255),
    type      varchar(255),
    repackage boolean not null,
    bl        varchar(255),
    pema      varchar(255),
    constraint "fk_containers-orders" foreign key (order_id) references orders (id)
);

create index "IDX_CONTAINERS_CODE" on containers (code);

-- Container.destinations @ElementCollection
create table container_destinations (
    id              bigint not null,
    type            varchar(255),
    code            varchar(255),
    fob             varchar(255),
    currency        varchar(255),
    product_details text,
    constraint "fk_destinations-containers" foreign key (id) references containers (id)
);

create index "IDX_CONTAINER_DESTINATIONS_CODE" on container_destinations (code);

create table free_loads (
    id       bigint generated by default as identity primary key,
    order_id bigint,
    patent   varchar(255),
    type     varchar(255),
    weight   varchar(255),
    guide    varchar(255),
    pema     varchar(255),
    constraint "fk_free_loads-orders" foreign key (order_id) references orders (id)
);

create index "IDX_FREE_LOADS_PATENT" on free_loads (patent);

-- FreeLoad.destinations @ElementCollection
create table free_load_destinations (
    id              bigint not null,
    type            varchar(255),
    code            varchar(255),
    fob             varchar(255),
    currency        varchar(255),
    product_details text,
    constraint "fk_destinations-free_loads" foreign key (id) references free_loads (id)
);

create index "IDX_FREE_LOAD_DESTINATIONS_CODE" on free_load_destinations (code);

create table documents (
    id         bigint generated by default as identity primary key,
    order_id   bigint,
    created_at timestamp(6) with time zone,
    name       varchar(255),
    resource   varchar(255),
    constraint "fk_documents-orders" foreign key (order_id) references orders (id)
);

create table costs (
    id                 bigint generated by default as identity primary key,
    order_id           bigint,
    amount             double precision not null,
    description        varchar(255),
    created_at         timestamp(6) with time zone,
    updated_at         timestamp(6) with time zone,
    type               varchar(255),
    created_by_user_id bigint not null,
    constraint "fk_costs-orders" foreign key (order_id) references orders (id)
);

create table notes (
    id                 bigint generated by default as identity primary key,
    order_id           bigint,
    author             varchar(255),
    content            text,
    created_at         timestamp(6) with time zone,
    updated_at         timestamp(6) with time zone,
    created_by_user_id bigint,
    constraint "fk_notes-orders" foreign key (order_id) references orders (id)
);
